if (!argumentName) return sendTrackedMessage(sock, remoteJid, 'Usage: !calc <expression>\nExample: !calc 2+2, !calc sqrt(144), !calc 2^10');
try {
  const expr = argumentName.trim()
    .replace(/\^/g, '**')
    .replace(/sqrt\(([^)]+)\)/gi, 'Math.sqrt($1)')
    .replace(/sin\(([^)]+)\)/gi, 'Math.sin($1)')
    .replace(/cos\(([^)]+)\)/gi, 'Math.cos($1)')
    .replace(/tan\(([^)]+)\)/gi, 'Math.tan($1)')
    .replace(/log\(([^)]+)\)/gi, 'Math.log10($1)')
    .replace(/ln\(([^)]+)\)/gi, 'Math.log($1)')
    .replace(/pi/gi, 'Math.PI')
    .replace(/abs\(([^)]+)\)/gi, 'Math.abs($1)');
  if (/[^0-9+\-*/().,%\sMath.sqrbcostalgepi]/.test(expr.replace(/Math\.[a-z]+/gi, ''))) {
    return sendTrackedMessage(sock, remoteJid, '❌ Invalid expression.');
  }
  const result = Function(`"use strict"; return (${expr})`)();
  if (typeof result !== 'number' || isNaN(result)) {
    return sendTrackedMessage(sock, remoteJid, '❌ Could not evaluate expression.');
  }
  await sendTrackedMessage(sock, remoteJid, `🧮 ${argumentName.trim()} = ${result}`);
} catch (e) {
  await sendTrackedMessage(sock, remoteJid, '❌ Invalid math expression.');
}
